use quince_core::{ring::RingVec,types::{Side,Trade}};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:1.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_mfi",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,pos:RingVec,neg:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{let p=x[0]as usize;Ok(Box::new(I{p,pos:RingVec::new(p),neg:RingVec::new(p)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{let f=t.price*t.qty;if t.side==Side::Buy{self.pos.push(f);self.neg.push(0.);}else{self.pos.push(0.);self.neg.push(f);};if self.pos.len()!=self.p{return None};let a=self.pos.iter().sum::<f64>();let b=self.neg.iter().sum::<f64>();Some(if b==0.{100.}else{100.-100./(1.+a/b)})}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;fn t(s:Side)->Trade{Trade{price:2.,qty:1.,time:Utc::now(),side:s,trade_id:1}}#[test]fn mfi(){let mut i=create(&[2.]).unwrap();i.on_trade(&t(Side::Buy));assert_eq!(i.on_trade(&t(Side::Buy)),Some(100.));}}
